<label>Plan name<input name="name" maxlength="100" value="{{ $plan?->name ?? old('name') }}" required></label><label>Price in TZS<input name="price" type="number" min="1" max="9999999" step="0.01" value="{{ $plan?->price ?? old('price') }}" required></label><input type="hidden" name="currency" value="TZS"><label>Duration in days<input name="duration_days" type="number" min="1" max="366" value="{{ $plan?->duration_days ?? old('duration_days',30) }}" required></label><label>Description<textarea name="description" maxlength="1000">{{ $plan?->description ?? old('description') }}</textarea></label><label>Availability<select name="is_active"><option value="1" @selected($plan?->is_active ?? true)>Available to publishers</option><option value="0" @selected($plan && !$plan->is_active)>Hidden</option></select></label>
